import { tags } from "typia";

/**
 * Detailed progress information for an individual file during upload operations. Provides real-time status, transfer metrics, and error information for monitoring file upload progress.
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IDiscussionBoardAttachmentFileProgress = {
  /**
   * Original filename of the file being uploaded, as provided by the user.
   *
   * @x-autobe-specification Captured from the original file metadata during upload initiation. Value remains constant throughout the upload process.
   */
  filename: string;

  /**
   * Total size of the file in bytes, representing the complete upload target.
   *
   * @x-autobe-specification Determined from the file's actual byte size during upload initialization. Used to calculate upload progress percentage when combined with bytesTransferred.
   */
  size: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Current upload status indicating where the file is in the upload process.
   *
   * @x-autobe-specification Tracked throughout the upload lifecycle: 'pending' (queued), 'uploading' (active transfer), 'completed' (successful), 'failed' (error occurred). Updated in real-time as upload progresses.
   */
  status: "pending" | "uploading" | "completed" | "failed";

  /**
   * Number of bytes successfully transferred so far, updated in real-time during upload.
   *
   * @x-autobe-specification Incremented in real-time during active upload. Used with 'size' to calculate progress percentage. Reset to 0 if upload fails and retries.
   */
  bytesTransferred: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Error message explaining upload failure, null when upload is successful or in progress.
   *
   * @x-autobe-specification Populated only when status is 'failed'. Contains descriptive error information from upload system (network errors, file validation failures, etc.). Null for successful uploads.
   */
  errorMessage: string | null;
};
